/* Technologies hidden on cards (still shown on detail pages) */
const HIDE_ON_CARDS = ["Scikit-learn"];

/* ---------- Reusable helpers ---------- */
const isPlaceholderUrl = (u) => !u || u === "#";
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

function imageBlock(src, alt, cls = "project-image") {
  return src
    ? `<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy" />`
    : `<div class="${cls} image-placeholder" role="img" aria-label="${esc(alt)} (image placeholder)"><span>Image placeholder</span></div>`;
}

function githubButton(url, cls = "button button-secondary", label = "GitHub") {
  return isPlaceholderUrl(url)
    ? `<a class="${cls} is-placeholder" href="#" aria-label="${label} (placeholder link)">${label}</a>`
    : `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
}

function techChips(list) {
  return `<ul class="tech-list" aria-label="Technologies">${list.map((t) => `<li class="tech-chip">${esc(t)}</li>`).join("")}</ul>`;
}

function projectCard(p) {
  return `<article class="project-card">
    ${imageBlock(p.image, p.title + " visualization")}
    <p class="project-type">${esc(p.type)}</p>
    <h3 class="project-title">${esc(p.title)}</h3>
    <p class="project-description">${esc(p.summary)}</p>
    ${techChips(p.tech.filter((t) => !HIDE_ON_CARDS.includes(t)))}
    <div class="card-actions">
      <a class="button button-primary" href="project.html?id=${encodeURIComponent(p.id)}">View Project</a>
      ${githubButton(p.github)}
    </div>
  </article>`;
}

function renderBlocks(blocks) {
  if (typeof blocks === "string") blocks = [blocks];
  return blocks
    .map((b) => {
      if (typeof b === "string") return `<p>${esc(b)}</p>`;
      if (b.h) return `<h3 class="detail-subheading">${esc(b.h)}</h3>`;
      if (b.ul) return `<ul class="detail-list">${b.ul.map((i) => `<li>${esc(i)}</li>`).join("")}</ul>`;
      if (b.code) return `<pre class="formula">${esc(b.code)}</pre>`;
      if (b.table) {
        const head = b.table.head.map((c) => `<th>${esc(c)}</th>`).join("");
        const rows = b.table.rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("");
        return `<div class="table-wrap"><table class="detail-table"><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div>`;
      }
      return "";
    })
    .join("");
}

function renderProjectDetail(p, root) {
  const d = DETAILS[p.id] || {};
  const section = (title, body) => `<section class="detail-section"><h2>${title}</h2>${body}</section>`;
  const body = (k) => renderBlocks(d[k] || "Details coming soon.");
  const visuals = d.visuals && d.visuals.length
    ? `<div class="visual-grid">${d.visuals.map((v) => imageBlock(v.src, v.alt || p.title, "project-image")).join("")}</div>`
    : `<div class="visual-grid">${imageBlock(null, p.title + " result visualization")}</div>`;
  root.innerHTML = `
    <a class="back-link" href="index.html#projects">&larr; Back to projects</a>
    <h1 class="detail-title">${esc(p.title)}</h1>
    <p class="detail-type">${esc(p.type)}</p>
    ${techChips(p.tech)}
    ${imageBlock(p.image, p.title + " visualization", "project-image detail-hero-image")}
    ${section("Project Overview", body("overview"))}
    ${section("Problem Statement", body("problem"))}
    ${section("Dataset Description", body("dataset"))}
    ${section("Data Preprocessing", body("preprocessing"))}
    ${section("Methodology and Algorithms", body("methodology"))}
    ${section("Implementation", body("implementation"))}
    ${section("Experiments", body("experiments"))}
    ${section("Results and Visualizations", body("results") + visuals)}
    ${section("Conclusion and Limitations", body("conclusion"))}
    ${section("GitHub Repository", `<p>${isPlaceholderUrl(p.github) ? "Repository link coming soon." : "Source code and notebooks are available on GitHub."}</p>` + githubButton(p.github, "button button-primary", "View on GitHub"))}
  `;
}

